import{_ as e,a,o,Y as r}from"./chunks/framework.BFAekxW2.js";const g=JSON.parse('{"title":"VLSI VS10xx Codec Comparison — VS1053b vs VS1063a vs VS1073a","description":"","frontmatter":{},"headers":[],"relativePath":"recaps/vsli-chips.md","filePath":"recaps/vsli-chips.md"}'),d={name:"recaps/vsli-chips.md"};function n(s,t,i,l,h,c){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="vlsi-vs10xx-codec-comparison-—-vs1053b-vs-vs1063a-vs-vs1073a" tabindex="-1">VLSI VS10xx Codec Comparison — VS1053b vs VS1063a vs VS1073a <a class="header-anchor" href="#vlsi-vs10xx-codec-comparison-—-vs1053b-vs-vs1063a-vs-vs1073a" aria-label="Permalink to “VLSI VS10xx Codec Comparison — VS1053b vs VS1063a vs VS1073a”">​</a></h1><p>Context: OpenPod currently uses the <strong>VS1053b</strong> for MP3/audio decoding. This compares it against the two newer pin-compatible parts in the same family, VS1063a and VS1073a (datasheets in <code>datasheets/</code>, prefixed <code>vs*</code>), plus VLSI&#39;s own 1-page comparison chart (<code>datasheets/vs10xx-comparison.pdf</code>).</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to “TL;DR”">​</a></h2><p><strong>Both VS1063a and VS1073a are pin-compatible drop-ins for VS1053b</strong> — same LQFP-48 package, and the full pin tables in all three datasheets are identical, pin-for-pin, pad name for pad name. VLSI&#39;s own text confirms it:</p><blockquote><p>&quot;VS1063a is a pin-compatible alternative for VS1053... has all the functionality of VS1053 (except MP1 and MIDI decoding)&quot;</p></blockquote><blockquote><p>&quot;VS1073a is a pin-compatible alternative for VS1053 and VS1063 with a change of core voltage regulator... has all the functionality of VS1063 (except AEC)&quot;</p></blockquote><table tabindex="0"><thead><tr><th></th><th>VS1053b (current)</th><th>VS1063a</th><th>VS1073a</th></tr></thead><tbody><tr><td>Pinout</td><td>reference</td><td><strong>identical</strong></td><td><strong>identical</strong> (but different CVDD voltage, see §5)</td></tr><tr><td>Formats</td><td>baseline</td><td>+FLAC (ROM), −MIDI, −MP1</td><td>++FLAC/ALAC/APE/AC-3/AIFF/DSD/Opus (all ROM), −MIDI, −AEC (MP1 comes back)</td></tr><tr><td>Power</td><td>baseline</td><td>same as VS1053b</td><td>not a clear win — see §2</td></tr><tr><td>DAC/ADC quality</td><td>baseline</td><td>marginally better THD</td><td>marginally better THD</td></tr><tr><td>RAM for user code</td><td>~0.5+ KiB data RAM</td><td>up to 80 KiB data RAM</td><td>32 KiB instruction RAM (2×) + up to 80 KiB data RAM</td></tr><tr><td>Status</td><td>mature, in production</td><td>mature</td><td><strong>preliminary datasheet, very new part</strong></td></tr></tbody></table><hr><h2 id="_1-formats-what-you-gain-lose" tabindex="-1">1. Formats: what you gain / lose <a class="header-anchor" href="#_1-formats-what-you-gain-lose" aria-label="Permalink to “1. Formats: what you gain / lose”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>VS1053b</th><th>VS1063a</th><th>VS1073a</th></tr></thead><tbody><tr><td>Decoders (ROM)</td><td>MP3, MP2, MP1, WAV, WMA, Ogg Vorbis, AAC, MIDI</td><td>MP3, MP2, WAV, WMA, Ogg Vorbis, AAC, <strong>FLAC</strong></td><td>MP3, MP2, <strong>MP1</strong>, WAV, WMA, Ogg Vorbis, AAC, FLAC, <strong>ALAC, Monkey&#39;s Audio (APE), AC-3, AIFF, DSD, Ogg Opus</strong></td></tr><tr><td>Decoders needing a loaded patch</td><td>FLAC</td><td>ALAC</td><td>— (everything above is in ROM, no patch needed)</td></tr><tr><td>Lost vs. VS1053b</td><td>—</td><td><strong>MP1, MIDI</strong></td><td><strong>MIDI</strong> (MP1 comes back), <strong>AEC</strong> (echo cancel, lost vs. VS1063a)</td></tr><tr><td>Encoders (ROM)</td><td>ADPCM, PCM</td><td>ADPCM, PCM, Ogg Vorbis, MP3, g.711, g.722</td><td>same as VS1063a <strong>+ FLAC</strong></td></tr><tr><td>Recording (ADC)</td><td>Stereo line / mono mic</td><td>Stereo line / mono mic</td><td>Stereo line / mono mic</td></tr></tbody></table><p>For an MP3/audio-player-transmitting-to-Bluetooth use case:</p><ul><li><strong>VS1063a</strong> — loses MIDI (General MIDI playback, unlikely to matter) and MP1 (rare MPEG layer-I audio, unlikely to matter). Gains FLAC decoding built into ROM (no patch juggling at boot), plus real recording/encoding to MP3/Ogg Vorbis/PCM if the device should ever record too.</li><li><strong>VS1073a</strong> — everything VS1063a has, minus AEC (acoustic echo cancellation — irrelevant for a music player, that&#39;s for speakerphone use), plus MP1 comes back, plus a lot more decoders (ALAC/Apple Lossless, FLAC, DSD, Opus, AC-3, Monkey&#39;s Audio) — all in ROM, no patches needed. This is the one to pick if lossless/hi-res playback (FLAC/ALAC/DSD) directly from the SD card matters.</li></ul><h2 id="_2-power-consumption" tabindex="-1">2. Power consumption <a class="header-anchor" href="#_2-power-consumption" aria-label="Permalink to “2. Power consumption”">​</a></h2><p>Datasheet power tables, Ogg Vorbis playback at full volume (128 kbit/s for VS1053b/VS1063a, 110 kbit/s for VS1073a), ~25°C:</p><table tabindex="0"><thead><tr><th></th><th>VS1053b</th><th>VS1063a</th><th>VS1073a</th></tr></thead><tbody><tr><td>CVDD voltage</td><td>1.8 V</td><td>1.8 V</td><td><strong>1.25 V</strong></td></tr><tr><td>AVDD current (30/33 Ω load)</td><td>11 mA</td><td>11 mA</td><td>16–21 mA (depends on VREF setting)</td></tr><tr><td>CVDD current</td><td>11 mA</td><td>11 mA</td><td><strong>5 mA</strong></td></tr><tr><td>Approx. total supply power</td><td>~56 mW</td><td>~56 mW</td><td>~60–76 mW</td></tr></tbody></table><p>The &quot;CVDD current 5 mA vs 11 mA&quot; number looks like a big win, and digital-core power really is roughly 3× lower on VS1073a thanks to the lower 1.25 V core voltage — but the analog output stage (AVDD) draws <em>more</em> current in VS1073a&#39;s own test condition, so total system power ends up roughly a wash to slightly worse in this specific test, not a clear win. Treat &quot;VS1073a is lower power&quot; as <strong>not proven</strong> by these numbers alone — the DAC/analog side dominates total power either way, and it didn&#39;t improve there. If power budget matters a lot, VS1063a is the safer bet (identical power numbers to the current VS1053b, just a more capable chip), while VS1073a&#39;s benefit is format support, not power.</p><p><strong>Caveat</strong>: the VS1073a datasheet is watermarked &quot;PRELIMINARY&quot; and dated 2026-05-26 — a very recently introduced (possibly not-yet-fully-validated or barely-released) part. Numbers could still move; worth checking current sourcing/stock and maybe waiting for a non-preliminary revision before committing.</p><h2 id="_3-dac-adc-quality" tabindex="-1">3. DAC/ADC quality <a class="header-anchor" href="#_3-dac-adc-quality" aria-label="Permalink to “3. DAC/ADC quality”">​</a></h2><p>Essentially a wash — VS1063a/VS1073a are marginally better than VS1053b, nothing regresses:</p><table tabindex="0"><thead><tr><th></th><th>VS1053b</th><th>VS1063a</th><th>VS1073a</th></tr></thead><tbody><tr><td>DAC resolution</td><td>18-bit</td><td>18-bit</td><td>18-bit</td></tr><tr><td>THD</td><td>0.07%</td><td><strong>0.04%</strong></td><td><strong>0.04%</strong></td></tr><tr><td>3rd harmonic distortion</td><td>0.02%</td><td><strong>0.01%</strong></td><td><strong>0.01%</strong></td></tr><tr><td>Dynamic range (IDR)</td><td>100 dB</td><td>100 dB</td><td>100 dB</td></tr><tr><td>SNR</td><td>94 dB</td><td>94 dB</td><td>94 dB</td></tr><tr><td>Mic SNR</td><td>70 dB</td><td>72 dB</td><td>72 dB</td></tr><tr><td>Line-in SNR/THD</td><td>90 dB / 0.014%</td><td>90 dB / 0.014%</td><td>90 dB / 0.014%</td></tr><tr><td>Headphone drive</td><td>30 Ω capable</td><td>30 Ω capable</td><td>30 Ω capable</td></tr></tbody></table><p>Not something you&#39;d hear a difference from in practice, but nothing to lose either.</p><h2 id="_4-ram-extensibility" tabindex="-1">4. RAM / extensibility <a class="header-anchor" href="#_4-ram-extensibility" aria-label="Permalink to “4. RAM / extensibility”">​</a></h2><p>This is a bigger practical difference than the raw numbers suggest:</p><ul><li><strong>VS1053b</strong>: 16 KiB instruction RAM, only <strong>~0.5+ KiB</strong> free data RAM for user code/patches.</li><li><strong>VS1063a</strong>: 16 KiB instruction RAM, <strong>up to 80 KiB</strong> data RAM (default ~4 KiB free, expandable).</li><li><strong>VS1073a</strong>: <strong>32 KiB</strong> instruction RAM (double VS1063a), up to 80 KiB data RAM.</li></ul><p>VS1053b&#39;s tiny data RAM is exactly why FLAC needs a loaded patch on it, and things get tight if DSP effects are wanted too. VS1063a/VS1073a essentially remove that ceiling — much more headroom for custom plugins, patches, or user DSP code running alongside the decoder.</p><h2 id="_5-other-feature-adds-vs1063a-and-vs1073a-only-not-on-vs1053b" tabindex="-1">5. Other feature adds (VS1063a and VS1073a only, not on VS1053b) <a class="header-anchor" href="#_5-other-feature-adds-vs1063a-and-vs1073a-only-not-on-vs1053b" aria-label="Permalink to “5. Other feature adds (VS1063a and VS1073a only, not on VS1053b)”">​</a></h2><ul><li><strong>AD Mixer</strong> — monitor the analog input while a stream is playing.</li><li><strong>PCM Mixer</strong> — mix a side-stream over the main decoded stream.</li><li><strong>Adjustable Speed Shifter</strong> — time-stretch/pitch playback speed.</li><li><strong>5-channel equalizer</strong> (alternative to bass/treble).</li><li><strong>I2S output width</strong>: VS1053b/VS1063a output 16-bit I2S; <strong>VS1073a goes to 16/32-bit</strong>.</li><li><strong>Full-duplex codec mode</strong> (simultaneous encode+decode) on both — VS1063a additionally has AEC on top of it, VS1073a doesn&#39;t.</li></ul><h2 id="_6-hardware-level-catch-the-cvdd-regulator" tabindex="-1">6. Hardware-level catch: the CVDD regulator <a class="header-anchor" href="#_6-hardware-level-catch-the-cvdd-regulator" aria-label="Permalink to “6. Hardware-level catch: the CVDD regulator”">​</a></h2><p>Pinout is identical across all three, but <strong>VS1073a needs a different CVDD voltage (1.25 V) vs VS1053b/VS1063a&#39;s 1.8 V</strong>. VLSI&#39;s own comparison note is explicit about this:</p><blockquote><p>&quot;While VS1003b can run from a single 2.8V power supply, using a separate CVDD regulator is highly recommended. With it you can populate the board with a different CVDD regulator and VS1053/63/73 or future IC that uses the same pinout (but newer technology). Use a 12.288MHz crystal, the LQFP-48 pinout from the VS1073a datasheet, and a separate CVDD regulator for your design to be future-proof in hardware.&quot;</p></blockquote><p>Design the CVDD regulator as a separately-populated part (not hardwired to a fixed 1.8V feedback network) to keep the board able to accept any of VS1053b/VS1063a/VS1073a interchangeably. If the current OpenPod board hardwired an 1.8V CVDD regulator assuming VS1053b, dropping in a VS1073a as-is would run its core out of spec — the fix is changing that one regulator (or its feedback resistors) to produce 1.25V; everything else on the board (footprint, all other pins, crystal, SPI/UART wiring) stays the same.</p><h2 id="_7-bottom-line" tabindex="-1">7. Bottom line <a class="header-anchor" href="#_7-bottom-line" aria-label="Permalink to “7. Bottom line”">​</a></h2><ul><li><strong>VS1063a</strong> — closest thing to a strict upgrade with zero hardware changes: same CVDD voltage, same power numbers, same DAC quality (slightly better THD), gains FLAC-in-ROM and real recording/encoding, loses only MIDI and MP1 (both unlikely to matter for an MP3 player). Very low-risk swap.</li><li><strong>VS1073a</strong> — much broader format support (FLAC/ALAC/DSD/Opus/AC-3, all in ROM) and double the instruction RAM, at the cost of needing to re-spec the CVDD regulator (1.25V instead of 1.8V) and no clear power win over VS1063a. Also currently a preliminary/very-new part — check availability before designing it in.</li></ul>',33)]))}const u=e(d,[["render",n]]);export{g as __pageData,u as default};
